package com.baraaoi.reallife.economy;

import com.google.gson.JsonPrimitive;
import net.minecraft.item.ItemStack;
import net.minecraft.item.Items;
import net.minecraft.nbt.CompoundNBT;
import net.minecraft.nbt.ListNBT;
import net.minecraft.nbt.StringNBT;

/** Справочник «Суровая реальная жизнь» — обычная подписанная книга, продаётся в торговых автоматах. */
public final class Guide {
    private Guide() {}

    public static final String TITLE = "Как выжить: справочник";

    static final String[] PAGES = {
            "§l  СУРОВАЯ\n  РЕАЛЬНАЯ\n    ЖИЗНЬ§r\n\nКарманный справочник гражданина.\n\n§8Издание 10-е (v1.10), дополненное. Цена 20₽ — дешевле, чем ошибки.",
            "§lСодержание§r\n1. Деньги и банк\n2. Кредиты\n3. Ипотека и дом\n4. МФО\n5. Коллекторы\n6. Казино\n7. Подполье\n8. ОБЭП\n9. Легальный бизнес\n10. Майнинг\n11. Телефон\n12. Гости\n13. Земля\n14. СЭС\n15. ЧП\n16. Под ключ и ТЦ",
            "§l1. Деньги§r\nРубли — это купюры 10, 100, 500, 1000, 5000. ПКМ купюрой по банку или банкомату — на счёт.\n\nНа счёт капает вклад каждый игровой день. Наличку могут отнять — не носи всё с собой.",
            "§l2. Кредиты§r\nКредит дают по рейтингу (300–850). Платёж списывается каждое утро.\n\nПлатил вовремя — рейтинг растёт, ставка падает. Просрочки — наоборот.\n\nСвой рейтинг: §o/reallife rating§r.",
            "§l2. Рейтинг§r\nТратить накопленное не страшно: банк помнит твой лучший остаток, рейтинг от покупок не падает.\n\nРабочий прибыльный бизнес каждый день добавляет к рейтингу (до +120).",
            "§l2. Автокредит§r\nУшёл в минус или повис штраф/просрочка — банк сам оформит кредит на 10 дней в пределах лимита по рейтингу.\n\nЛимит кончился — тогда уже Жора.",
            "§l3. Ипотека§r\nВ банке выбираешь дом: от землянки до пентхауса. Бригада строит бесплатно, платишь ипотеку.\n\nНе платишь — дом снесут, вещи конфискуют.",
            "§l3. Дом сразу§r\nЕсть деньги — жми «Купить сразу» в окне ипотеки: полная цена со счёта и налички, без рейтинга и проверки дохода.\n\nОрдер тот же, бригада строит бесплатно, а дом не в залоге.",
            "§l4. МФО§r\n«Шайкин и Ко» дают всем. Под сложный процент.\n\nДолг растёт каждый день. Не вернёшь — приедут Вован и братки, увезут в яму, где придётся копать долг кайлом.",
            "§l5. Коллекторы§r\nЗа долг банку:\nЖора → Александр → полиция → тюрьма и конфискация.\n\nЖоре можно заплатить прямо в руки (ПКМ). Взятка иногда помогает. Иногда — нет.",
            "§l6. Казино§r\n«Три семёрки»: монетка, слоты, рулетка, «Мама Анархия».\n\nКазино всегда в плюсе. Зелье удачи и клевер немного помогают. Немного.",
            "§l7. Подполье§r\nПечатный станок ставится только на своей земле (дом, подвал, участок). Печатает грязные деньги в «Сундук цеха».\n\nГрязные деньги нельзя положить в банк — их надо отмыть.",
            "§l7. Отмыв§r\n• ООО «Отмыв» — 30% комиссии\n• МФО — 50%\n• Касса своего заведения — 13% налога, но безопасно лишь до 15% ВЧЕРАШНЕЙ прибыли (в ТЦ — 25%). Был убыток или ноль — отмывать нельзя.",
            "§l8. ОБЭП§r\nЕсли станок увидит NPC — жди звонка и рейда. Опера роют тоннель прямо к станку.\n\nШтраф, конфискация, СИЗО. Станки прячь за стенами без окон.",
            "§l8. Подозрительный тип§r\nБродит вокруг домов, заходит в двери, заглядывает к станкам и всё записывает.\n\nДашь по шее — убежит. Но кто знает, успел ли он позвонить...",
            "§l9. Бизнес§r\nТелефон → Бизнес → купи лицензию. ПКМ ею по блоку на своей земле — там встанет главная касса.\n\nЗдание строишь сам! Зона заведения — 8 блоков вокруг кассы.",
            "§l9. Оборудование§r\nТелефон → Бизнес → Оборудование.\n\nШаурма: гриль, холодильник\nМаркет: 3 полки, холодильник\nМойка: 2 мойки\n+ по кассе в каждый комплект.\n\n+ ОДИН складской стеллаж на всё заведение.",
            "§l9. Ещё комплекты§r\nКарьер: дробилка\nЛомбард: сейф, 2 витрины\nАЗС: 2 колонки, полка\nТехника: 3 витрины, 2 полки\n\nКомплект = 1 работник.",
            "§l9. Работники§r\nСколько полных комплектов — столько работников (до потолка вида). Нанять/уволить — ПКМ по любой кассе в зоне.\n\nКаждый получает зарплату, даже если сидит без дела.",
            "§l9. Сырьё§r\nКаждый работник съедает 1 коробку в день. Коробки не стакаются: 1 коробка = 1 слот. Опт: партия 8 коробок. Газель раскладывает их по полкам, потом на склад. Больше стеллажей — больше запас.",
            "§l9. Прибыль§r\nВыручка = база × работники × удача × доля сырья − зарплаты.\n\nНет сырья — простой и убыток. Удачные дни бывают: блогер, свадьба, фестиваль.\n\nС v1.10 выручка выше в 1,75 раза.",
            "§l10. Майнинг§r\nФерма + материнка, процессор, память, БП, кулер и 1–4 видеокарты.\n\nБиткоины копятся в ферме; продавай на бирже в телефоне. Курс скачет.",
            "§l10. Криптобиржа§r\nТелефон → Крипта. Монеты: BTC, ETH, TON, DOGE. Покупай со счёта, продавай обратно, комиссия 1%.\n\nКурс меняется каждые 20 секунд, новости двигают его на ±15–40%. DOGE скачет сильнее всех.",
            "§l11. Телефон§r\nСчёт, снятие налички, кредит онлайн, опт, бизнес, криптобиржа.\n\nПродаётся у продавца ресурсов в банке. В тюрьме телефон изымают.",
            "§l12. Гости§r\nК тебе будут заходить: налоговая, сантехник, цыганка, риелтор, дед Митрич, философ...\n\nКто-то полезен, кто-то опасен. Решай сам — кнопками в чате.",
            "§l12. Кочевникам§r\nБез дома, в шахте или далеко от дома гости приходят чаще: участковый, ДПС, бомж Валера, коробейник, автостопщик, кладоискатель.\n\nПод землёй: чёрный копатель и заблудившийся спелеолог.",
            "§l13. Земля§r\nСтроишь на чужой земле больше 48 блоков — придёт инспектор.\n\n§o/reallife land buy§r — купить сразу участок 3×3 чанка (48×48 блоков). Платишь только за свободные чанки.",
            "§l14. СЭС§r\nПроверяет заведение: крыша и стены (не земля!), свет, паутина, монстры, раковина (котёл с водой), просрочка, медкнижки.\n\n3 нарушения — пломба на 2 дня.",
            "§l14. Документы§r\nКасса → «Документы»: медкнижки и патенты, 300₽ на работника на 7 дней.\n\nБез них миграционная служба депортирует работников и берёт по 3000₽.",
            "§l15. ЧП§r\nПожар: 60 секунд на тушение, потом пожарные и штраф.\nОбвал: «порода трещит» — беги, 3 секунды.\nДомушник ночью: бей, пока не вскрыл сундук.",
            "§l16. Под ключ§r\nТелефон → Бизнес → «Под ключ»: лицензия + бригада + всё оборудование на максимум работников.\n\nПКМ договором по земле — встанет здание 13×13 со светом, вывеской и раковиной. Останется сырьё и найм.",
            "§l16. Торговый центр§r\nТелефон → Бизнес → ТЦ, 150 000₽. Огромный зал 71×45, 8 мест: шаурма, маркет, ломбард, техника — по 2.\n\nПКМ обычной лицензией по метке в центре места.",
            "§l16. Выгода ТЦ§r\nЗаведения в ТЦ: прибыль +50%, безопасный отмыв 25% вчерашней прибыли (вне ТЦ 15%).\n\nОткрывать заведения в ТЦ может только его владелец.",
            "§lПоследний совет§r\nНе бери в долг то, что не можешь отдать.\n\nНе печатай то, что не можешь отмыть.\n\nИ не бей подозрительных типов при свидетелях.\n\n§8— Реал Банк"};

    public static ItemStack book() {
        ItemStack st = new ItemStack(Items.WRITTEN_BOOK);
        CompoundNBT tag = st.getOrCreateTag();
        tag.putString("title", TITLE);
        tag.putString("author", "Реал Банк");
        tag.putInt("generation", 0);
        tag.putBoolean("resolved", true);
        ListNBT pages = new ListNBT();
        for (String p : PAGES) pages.add(StringNBT.valueOf(new JsonPrimitive(p).toString()));
        tag.put("pages", pages);
        return st;
    }
}
